window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8b3b417fe56ad075"]={"versions": [{"id": "FIG-8b3b417fe56ad075", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Berechnungsschritts „Compute offset“ innerhalb des AUTOSAR E2E Profile 5 (End-to-End Communication Protection Protocol). Das Diagramm beschreibt den internen Kontrollfluss zur Umrechnung der Offset-Konfiguration von Bit- in Byte-Einheiten für die E2E-Funktionen <code>E2E_P05Protect()</code> und <code>E2E_P05Check()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionen / Aufrufkontext (linke Seitenleiste mit Unendlichkeits-Symbol/Teilaktivitätssymbol):\n<ul class=\"fig-list\"><li><code>E2E_P05Protect()</code>\n</li><li><code>E2E_P05Check()</code>\n</li></ul>\n</li><li>Datenstrukturen und Variablen:\n<ul class=\"fig-list\"><li><code>Config-&gt;Offset</code>: Konfigurationsparameter (Bit-Offset des E2E-Headers innerhalb der Nutzdaten).\n</li><li><code>Offset</code>: Lokale Variable vom Datentyp <code>uint16</code> zur Aufnahme des berechneten Byte-Offsets.\n</li></ul>\n</li><li>Notiz-Element: <code>compute local variable uint16 Offset, which is in [byte]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start über den Initialknoten (ausgefüllter schwarzer Kreis).\n</li><li>Ausführung des Aktivitätsknotens <code>Offset = Config-&gt;Offset / 8</code> (Ganzzahldivision des konfigurierten Bit-Offsets durch 8 zur Bestimmung des Byte-Offsets).\n</li><li>Übergang in den Endknoten (Aktivitätsendknoten / Bullseye).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation gemäß Anforderung <code>[PRS_E2E_00469]</code>. Bei der Implementierung von <code>E2E_P05Protect()</code> und <code>E2E_P05Check()</code> muss vor der E2E-Header-Verarbeitung der Byte-Offset als lokale 16-Bit-Ganzzahl (<code>uint16</code>) berechnet werden. Der Wert <code>Config-&gt;Offset</code> muss einem ganzzahligen Vielfachen von 8 Bits entsprechen bzw. die Division <code>/ 8</code> legt den Startbyte-Index fest.</p>"}, {"id": "FIG-cba5b91cfe388c08", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Berechnungsschritts „Compute offset“ innerhalb des AUTOSAR E2E Profile 5 (End-to-End Communication Protection Protocol). Das Diagramm beschreibt den internen Kontrollfluss zur Umrechnung der Offset-Konfiguration von Bit- in Byte-Einheiten für die E2E-Funktionen <code>E2E_P05Protect()</code>, <code>E2E_P05Check()</code> und <code>E2E_P05Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionen / Aufrufkontext (linke Seitenleiste mit Unendlichkeits-Symbol/Teilaktivitätssymbol):\n<ul class=\"fig-list\"><li><code>E2E_P05Protect()</code>\n</li><li><code>E2E_P05Check()</code>\n</li><li><code>E2E_P05Forward()</code>\n</li></ul>\n</li><li>Datenstrukturen und Variablen:\n<ul class=\"fig-list\"><li><code>Config-&gt;Offset</code>: Konfigurationsparameter (Bit-Offset des E2E-Headers innerhalb der Nutzdaten).\n</li><li><code>Offset</code>: Lokale Variable vom Datentyp <code>uint16</code> zur Aufnahme des berechneten Byte-Offsets.\n</li></ul>\n</li><li>Notiz-Element: <code>compute local variable uint16 Offset, which is in [byte]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start über den Initialknoten (ausgefüllter schwarzer Kreis).\n</li><li>Ausführung des Aktivitätsknotens <code>Offset = Config-&gt;Offset / 8</code> (Ganzzahldivision des konfigurierten Bit-Offsets durch 8 zur Bestimmung des Byte-Offsets).\n</li><li>Übergang in den Endknoten (Aktivitätsendknoten / Bullseye).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation gemäß Anforderung <code>[PRS_E2E_00469]</code>. Bei der Implementierung von <code>E2E_P05Protect()</code>, <code>E2E_P05Check()</code> und <code>E2E_P05Forward()</code> muss vor der E2E-Header-Verarbeitung der Byte-Offset als lokale 16-Bit-Ganzzahl (<code>uint16</code>) berechnet werden. Der Wert <code>Config-&gt;Offset</code> muss einem ganzzahligen Vielfachen von 8 Bits entsprechen bzw. die Division <code>/ 8</code> legt den Startbyte-Index fest.</p>"}, {"id": "FIG-e4f494f53014d9b6", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Berechnungsschritts „Compute offset“ innerhalb des AUTOSAR E2E Profile 5 (End-to-End Communication Protection Protocol). Das Diagramm beschreibt den internen Kontrollfluss zur Umrechnung der Offset-Konfiguration von Bit- in Byte-Einheiten für die E2E-Funktionen <code>E2E_P05Protect()</code>, <code>E2E_P05Check()</code> und <code>E2E_P05Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Funktionen / Aufrufkontext (linke Seitenleiste mit Unendlichkeits-Symbol/Teilaktivitätssymbol):\n<ul class=\"fig-list\"><li><code>E2E_P05Protect()</code>\n</li><li><code>E2E_P05Check()</code>\n</li><li><code>E2E_P05Forward()</code>\n</li></ul>\n</li><li>Datenstrukturen und Variablen:\n<ul class=\"fig-list\"><li><code>Config-&gt;Offset</code>: Konfigurationsparameter (Bit-Offset des E2E-Headers innerhalb der Nutzdaten).\n</li><li><code>Offset</code>: Lokale Variable vom Datentyp <code>uint16</code> zur Aufnahme des berechneten Byte-Offsets.\n</li></ul>\n</li><li>Notiz-Element: <code>compute local variable uint16 Offset, which is in [byte]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start über den Initialknoten (ausgefüllter schwarzer Kreis).\n</li><li>Ausführung des Aktivitätsknotens <code>Offset = Config-&gt;Offset / 8</code> (Ganzzahldivision des konfigurierten Bit-Offsets durch 8 zur Bestimmung des Byte-Offsets).\n</li><li>Übergang in den Endknoten (Aktivitätsendknoten / Bullseye).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation gemäß Anforderung <code>[PRS_E2E_00469]</code>. Bei der Implementierung von <code>E2E_P05Protect()</code>, <code>E2E_P05Check()</code> und <code>E2E_P05Forward()</code> muss vor der E2E-Header-Verarbeitung der Byte-Offset als lokale 16-Bit-Ganzzahl (<code>uint16</code>) berechnet werden. Der Wert <code>Config-&gt;Offset</code> muss einem ganzzahligen Vielfachen von 8 Bits entsprechen bzw. die Division <code>/ 8</code> legt den Startbyte-Index fest.</p>"}], "trans": [{"from": "FIG-8b3b417fe56ad075", "to": "FIG-cba5b91cfe388c08", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Zuordnungsknoten / Funktionssymbol <code>E2E_P05Forward()</code> links neben dem Aktivitätsablauf hinzugefügt.\n</li></ul>"}, {"from": "FIG-cba5b91cfe388c08", "to": "FIG-e4f494f53014d9b6", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
